function clean(){sessionFresh=true;ordersFresh=true;savePending=false;connectionBanner.hidden=true;historyReviewCode=null;historyReviewPending=false;sessionEntryPending=false;clearExport();viewVersion++;ordersReady=false;rosterReady=false;renderedOrderKey='';teamEditor=null;clearTimeout(rosterTimer);rosterTimer=null;orderUnsub?.();orderUnsub=null;currentOrderUid=null;marketReady='';marketLoading='';subscriptions.forEach(f=>f());subscriptions=[];rosterSubs.forEach(f=>f());rosterSubs.clear();clearInterval(tickHandle);session=null;orders={};roster=[];classOrders={};phaseKey='';studentPreview=null;demoOffset=0;}
function updateConnection(){
 const active=session&&!staffView&&!studentPreview;
 connectionBanner.hidden=!active;
 if(!active)return;
 const waiting=!connected||!sessionFresh||(currentOrderUid&&!ordersFresh);
 connectionBanner.dataset.state=savePending?'saving':waiting?'waiting':'ready';
 connectionBanner.textContent='Session '+session.code+' · '+(!connected?'Offline. Reconnect to receive team updates and save. The clock keeps running.':savePending?'Save pending. Keep this page open until confirmation.':waiting?'Reconnecting… waiting for the latest session and saved decisions.':session.status==='lobby'?'Connected · waiting for your instructor.':'Connected · saved decisions are up to date.');
 const button=$('save-order');if(button)button.disabled=waiting||savePending||(session.mode==='team'&&decisionOwner(session,user.uid)!==user.uid);
}
function resumeVisibleGame(){
 connected=pageWindow.navigator.onLine!==false;
 if(connected&&retryAccount){retryAccount();return;}
 if(!session||studentPreview)return;
 const p=phase(),key=p.index+':'+p.kind+':'+session.status;
 if(key!==phaseKey||$('retry-market'))renderSession();else updateClock();
 updateConnection();
}
