function verificationAction(fn){return action(async()=>{const status=$('verification-status');if(status)status.textContent='Checking…';try{await fn();}catch(error){if($('verification-status'))$('verification-status').textContent=friendlyAuthError(error);else failure(error);}});}
function openAuth(mode){authMode=mode;$('registration-fields').hidden=mode!=='register';for(const id of ['first-name','last-name','university-id'])$(id).required=mode==='register';document.querySelector('.divider').hidden=mode==='reset';$('auth-title').textContent=mode==='register'?'Your seat at the table.':mode==='reset'?'Reset your password.':'Welcome back.';$('auth-submit').textContent=mode==='register'?'Create account →':mode==='reset'?'Send reset email':'Log in →';$('password-label').hidden=mode==='reset';$('password-help').hidden=mode!=='register';if(mode==='register')$('password').setAttribute('aria-describedby','password-help');else $('password').removeAttribute('aria-describedby');$('password').required=mode!=='reset';$('password').minLength=mode==='register'?8:1;$('password').autocomplete=mode==='register'?'new-password':'current-password';$('google').hidden=mode==='reset';$('auth-error').textContent='';$('auth-status').textContent='';const code=sessionCodeFromUrl(location.href);$('auth-context').hidden=!code;$('auth-context').textContent=code?'Session '+code+' · your session ID is kept while you sign in.':'';$('auth-help').textContent=mode==='reset'?'Enter the email you use for Fast Fashion Ops. Open the reset link, set your password, then return here to log in.':'Use your Fast Fashion Ops account. Email registration requires verification. Instructor access is granted by the administrator.';document.querySelectorAll('[data-auth]').forEach(b=>b.hidden=b.dataset.auth===mode||(mode==='reset'&&b.dataset.auth==='register'));if(!$('auth').open)$('auth').showModal();$('auth').scrollTop=0;$(mode==='register'?'first-name':'email').focus({preventScroll:true});}
